async def act(page):
    import asyncio
    import urllib.parse

    # The comment we need to post and the search keyword (full title)
    comment_text = "Appreciate the detailed explanation."
    keyword = "Settle Down, Nerds. AI Is A Normal Technology"

    # 1) Use the site-aware search helper from the knowledge base to locate the post.
    #    Utility: create_curated_collection_by_search is designed to interact with
    #    the site's visible search widget (role="complementary" / searchbox) and
    #    return discovered posts. It's the most appropriate KB function for finding
    #    a specific post by title and is therefore used first.
    try:
        results = await create_curated_collection_by_search(
            page,
            keyword=keyword,
            max_results=50,
            resolve_links=True,
        )
    except Exception:
        results = []

    target_url = None

    # 2) Inspect helper results for a matching title (case-insensitive substring match)
    for r in (results or []):
        try:
            title = (r.get("title") or "").strip()
            href = r.get("url")
        except Exception:
            title = ""
            href = None
        if not title:
            continue
        low = title.lower()
        if "settle down" in low or "ai is a normal" in low or "ai is a normal technology" in low:
            target_url = href
            break

    # 3) Fallback: if the helper did not find it, scan visible links on the homepage
    #    Utility: a direct link-scan using accessibility roles is a robust fallback
    #    when the visible search widget isn't present or the helper couldn't find results.
    if not target_url:
        try:
            await page.goto("/")  # relative goto per guidance
            try:
                await page.wait_for_load_state("networkidle", timeout=3000)
            except Exception:
                await asyncio.sleep(0.5)
        except Exception:
            # ignore navigation errors and proceed to scanning
            await asyncio.sleep(0.1)

        links = page.get_by_role("link")
        try:
            link_count = await links.count()
        except Exception:
            link_count = 0

        for i in range(link_count):
            try:
                text = (await links.nth(i).inner_text()).strip().lower()
            except Exception:
                text = ""
            if "settle down" in text or "ai is a normal" in text or "ai is a normal technology" in text:
                try:
                    href = await links.nth(i).get_attribute("href")
                except Exception:
                    href = None
                if href:
                    target_url = urllib.parse.urljoin(page.url, href)
                    break

    # 4) If no post found, report and stop.
    if not target_url:
        print("POST_NOT_FOUND")
        return

    # 5) Navigate to the post page
    await page.goto(target_url)
    try:
        await page.wait_for_load_state("networkidle", timeout=5000)
    except Exception:
        # small grace period for client-side rendering
        await asyncio.sleep(1)

    # 6) Attempt to find a comment textbox inside any form and submit the comment.
    #    Utility: interacting with role="form" and its child role="textbox" is
    #    accessibility-role-centric and robust across themes.
    posted = False

    form_locator = page.get_by_role("form")
    try:
        form_count = await form_locator.count()
    except Exception:
        form_count = 0

    for i in range(form_count):
        form = form_locator.nth(i)
        tb_locator = form.get_by_role("textbox")
        try:
            tb_count = await tb_locator.count()
        except Exception:
            tb_count = 0
        if tb_count > 0:
            try:
                await tb_locator.nth(0).fill(comment_text)
            except Exception:
                pass

            # Prefer clicking named buttons inside the same form using the full parent->child path
            clicked = False
            for name in ("Post Comment", "Submit", "Post", "Leave Comment"):
                btn_named = form.get_by_role("button", name=name)
                try:
                    if await btn_named.count() > 0:
                        await btn_named.first.click()
                        clicked = True
                        break
                except Exception:
                    continue

            if not clicked:
                # Fallback: click the first button inside the form
                btns = form.get_by_role("button")
                try:
                    if await btns.count() > 0:
                        await btns.nth(0).click()
                        clicked = True
                except Exception:
                    clicked = False

            posted = clicked
            if posted:
                break

    # 7) Global fallback: fill the first textbox on the page and click common submit buttons
    if not posted:
        textbox = page.get_by_role("textbox")
        try:
            tb_total = await textbox.count()
        except Exception:
            tb_total = 0
        if tb_total > 0:
            try:
                await textbox.first.fill(comment_text)
            except Exception:
                pass

            clicked = False
            for name in ("Post Comment", "Submit", "Post", "Leave Comment"):
                btn = page.get_by_role("button", name=name)
                try:
                    if await btn.count() > 0:
                        await btn.first.click()
                        clicked = True
                        break
                except Exception:
                    continue

            if not clicked:
                any_btn = page.get_by_role("button")
                try:
                    if await any_btn.count() > 0:
                        await any_btn.first.click()
                        clicked = True
                except Exception:
                    clicked = False

            posted = clicked

    # 8) Final reporting
    if posted:
        print("COMMENT_POSTED")
    else:
        print("COMMENT_BOX_NOT_FOUND")

